 38	    public CheckoutSummary calculateSummary(CheckoutSummaryRequest request) {
 39	        validateRequest(request);
 40	
 41	        List<Product> products = getAndValidateProducts(request.getItems());
 42	        validateCoupon(request.getCoupon(), request.getItems(), products);
 43	
 44	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), products);
 45	        BigDecimal couponDiscount = calculateCouponDiscount(request.getCoupon(), request.getItems(),
 46	                products, productsSubtotal, request.getCustomer().getCpf());
 47	
 48	        BigDecimal shippingCost = BigDecimal.ZERO;
 49	        Integer deliveryDays = 0;
 50	        if (request.getShippingMethod() != ShippingMethod.STORE_PICKUP &&
 51	            request.getClubTier() != ClubTier.GOLD) {
 52	            ShippingInfo shippingInfo = calculateShipping(request.getShippingMethod(),
 53	                    request.getZipCode(), request.getItems(), products, request.getRegion());
 54	            shippingCost = shippingInfo.cost;
 55	            deliveryDays = shippingInfo.days;
 56	        } else if (request.getShippingMethod() != ShippingMethod.STORE_PICKUP &&
 57	                   request.getClubTier() == ClubTier.GOLD) {
 58	            ShippingInfo shippingInfo = calculateShipping(request.getShippingMethod(),
 59	                    request.getZipCode(), request.getItems(), products, request.getRegion());
 60	            deliveryDays = shippingInfo.days;
 61	        } else if (request.getShippingMethod() == ShippingMethod.STORE_PICKUP) {
 62	            deliveryDays = STORE_PICKUP_DAYS;
 63	        }
 64	
 65	        BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
 66	
 67	        BigDecimal subtotalBeforePayment = CurrencyUtils.add(productsSubtotal,
 68	                CurrencyUtils.subtract(BigDecimal.ZERO, couponDiscount), shippingCost, insurance);
 69	
 70	        BigDecimal paymentAdjustment = calculatePaymentAdjustment(subtotalBeforePayment,
 71	                request.getPaymentMethod(), request.getInstallments());
 72	
 73	        BigDecimal finalTotal = CurrencyUtils.add(subtotalBeforePayment, paymentAdjustment);
 74	
 75	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
 76	        BigDecimal installmentAmount = calculateInstallmentAmount(finalTotal, installments);
 77	
 78	        BigDecimal nextPurchaseCredit = calculateNextPurchaseCredit(request.getClubTier(), productsSubtotal);
 79	
 80	        Boolean gift = request.getClubTier() == ClubTier.GOLD &&
 81	                      productsSubtotal.compareTo(new BigDecimal("500.00")) > 0;
 82	
 83	        return CheckoutSummary.builder()
 84	                .productsSubtotal(productsSubtotal)
 85	                .couponDiscount(couponDiscount)
 86	                .shippingCost(shippingCost)
 87	                .deliveryDays(deliveryDays)
 88	                .insurance(insurance)
 89	                .paymentAdjustment(paymentAdjustment)
 90	                .finalTotal(finalTotal)
 91	                .installments(installments)
 92	                .installmentAmount(installmentAmount)
 93	                .nextPurchaseCredit(nextPurchaseCredit)
 94	                .gift(gift)
 95	                .build();
 96	    }
 97	
 98	    private void validateRequest(CheckoutSummaryRequest request) {
 99	        if (request.getItems() == null || request.getItems().isEmpty()) {
100	            throw new OrderServiceException("INVALID_ORDER", "Cart is empty", HttpStatus.UNPROCESSABLE_ENTITY);
101	        }
102	
103	        Set<String> skus = new HashSet<>();
104	        for (var item : request.getItems()) {
105	            if (item.getSku() == null || item.getSku().isEmpty()) {
106	                throw new OrderServiceException("INVALID_ORDER", "Item SKU is missing", HttpStatus.UNPROCESSABLE_ENTITY);
107	            }
108	            if (item.getQuantity() == null || item.getQuantity() <= 0) {
109	                throw new OrderServiceException("INVALID_ORDER", "Item quantity must be positive", HttpStatus.UNPROCESSABLE_ENTITY);
110	            }
111	            if (!skus.add(item.getSku())) {
112	                throw new OrderServiceException("INVALID_ORDER", "Duplicate SKU in cart", HttpStatus.UNPROCESSABLE_ENTITY);
113	            }
114	        }
115	
116	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null ||
117	            request.getCustomer().getCpf().isEmpty() || request.getCustomer().getEmail() == null ||
118	            request.getCustomer().getEmail().isEmpty()) {
119	            throw new OrderServiceException("INVALID_ORDER", "Customer CPF and email are required", HttpStatus.UNPROCESSABLE_ENTITY);
120	        }
121	
122	        if (request.getClubTier() == null) {
123	            throw new OrderServiceException("INVALID_CLUB_TIER", "Club tier is required", HttpStatus.UNPROCESSABLE_ENTITY);
124	        }
125	
126	        if (request.getRegion() == null) {
127	            throw new OrderServiceException("INVALID_REGION", "Region is required", HttpStatus.UNPROCESSABLE_ENTITY);
128	        }
129	
130	        if (request.getZipCode() == null || request.getZipCode().length() != 8 ||
131	            !request.getZipCode().matches("\\d{8}")) {
132	            throw new OrderServiceException("INVALID_ZIP_CODE", "Invalid ZIP code", HttpStatus.UNPROCESSABLE_ENTITY);
133	        }
134	
135	        if (request.getShippingMethod() == null) {
136	            throw new OrderServiceException("INVALID_SHIPPING_METHOD", "Shipping method is required", HttpStatus.UNPROCESSABLE_ENTITY);
137	        }
138	
139	        if (request.getPaymentMethod() == null) {
140	            throw new OrderServiceException("INVALID_PAYMENT_METHOD", "Payment method is required", HttpStatus.UNPROCESSABLE_ENTITY);
141	        }
142	
143	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
144	        if (installments < 1 || installments > 12) {
145	            throw new OrderServiceException("INVALID_INSTALLMENTS", "Invalid number of installments", HttpStatus.UNPROCESSABLE_ENTITY);
146	        }
147	
148	        if (request.getPaymentMethod() == PaymentMethod.PIX || request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
149	            if (installments != 1) {
150	                throw new OrderServiceException("INVALID_INSTALLMENTS", "PIX and BANK_SLIP do not support installments", HttpStatus.UNPROCESSABLE_ENTITY);
151	            }
152	        }
153	    }
