407	@Service
408	@RequiredArgsConstructor
409	public class TransLogClient {
410	    @Value("${translog.url:http://localhost:8081}")
411	    private String translogUrl;
412	
413	    private final ObjectMapper objectMapper;
414	
415	    public Optional<TransLogQuoteResponse> getQuote(String zipCode, Integer weightGrams, String service) {
416	        try {
417	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
418	                    translogUrl, zipCode, weightGrams, service);
419	
420	            HttpClient httpClient = HttpClient.newBuilder()
421	                    .connectTimeout(Duration.ofSeconds(2))
422	                    .build();
423	
424	            HttpRequest request = HttpRequest.newBuilder()
425	                    .uri(URI.create(url))
426	                    .timeout(Duration.ofSeconds(2))
427	                    .GET()
428	                    .build();
429	
430	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
431	
432	            if (response.statusCode() == 200) {
433	                @SuppressWarnings("unchecked")
434	                Map<String, Object> responseBody = objectMapper.readValue(response.body(), Map.class);
435	
436	                if (responseBody.containsKey("error")) {
437	                    if ("ZIP_NOT_SERVED".equals(responseBody.get("error"))) {
438	                        return Optional.empty();
439	                    }
440	                    return Optional.empty();
441	                }
442	
443	                Integer priceCents = ((Number) responseBody.get("price_cents")).intValue();
444	                Integer etaHours = ((Number) responseBody.get("eta_hours")).intValue();
445	
446	                return Optional.of(TransLogQuoteResponse.builder()
447	                        .priceCents(priceCents)
448	                        .etaHours(etaHours)
449	                        .build());
450	            }
451	
452	            return Optional.empty();
453	        } catch (IOException | InterruptedException e) {
454	            return Optional.empty();
455	        }
456	    }
457	
458	    @lombok.Data
459	    @lombok.NoArgsConstructor
460	    @lombok.AllArgsConstructor
461	    @lombok.Builder
462	    public static class TransLogQuoteResponse {
463	        private Integer priceCents;
464	        private Integer etaHours;
465	    }
466	}
467	package com.loja.orderservice.util;
468	
469	import java.math.BigDecimal;
470	import java.math.RoundingMode;
471	
472	public class CurrencyUtils {
473	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
474	
475	    public static BigDecimal roundToCents(BigDecimal value) {
476	        if (value == null) {
477	            return BigDecimal.ZERO;
478	        }
479	        return value.setScale(2, ROUNDING_MODE);
480	    }
481	
482	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
483	        return roundToCents(a.multiply(b));
484	    }
485	
486	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
487	        return roundToCents(a.divide(b, 10, ROUNDING_MODE));
488	    }
489	
490	    public static BigDecimal add(BigDecimal... values) {
491	        BigDecimal result = BigDecimal.ZERO;
492	        for (BigDecimal value : values) {
493	            if (value != null) {
494	                result = result.add(value);
495	            }
496	        }
497	        return roundToCents(result);
498	    }
499	
500	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
501	        return roundToCents(a.subtract(b));
502	    }
503	}

