cat > /tmp/run/Stub.java <<'EOF'
import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.util.*;

public class Stub {
    static volatile String body = "{\"price_cents\": 3310, \"eta_hours\": 41}";
    static volatile int status = 200;
    static volatile long delayMs = 0;
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9090), 0);
        s.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
        s.createContext("/v2/quote", ex -> {
            System.out.println("QUOTE " + ex.getRequestURI());
            System.out.flush();
            try { if (delayMs > 0) Thread.sleep(delayMs); } catch (InterruptedException e) {}
            byte[] b = body.getBytes();
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(status, b.length);
            ex.getResponseBody().write(b); ex.close();
        });
        s.createContext("/set", ex -> {
            Map<String,String> q = new HashMap<>();
            String qs = ex.getRequestURI().getRawQuery();
            if (qs != null) for (String p : qs.split("&")) { String[] kv = p.split("=",2); q.put(kv[0], URLDecoder.decode(kv[1], "UTF-8")); }
            if (q.containsKey("body")) body = q.get("body");
            if (q.containsKey("status")) status = Integer.parseInt(q.get("status"));
            if (q.containsKey("delay")) delayMs = Long.parseLong(q.get("delay"));
            byte[] b = ("ok " + status + " " + delayMs + " " + body).getBytes();
            ex.sendResponseHeaders(200, b.length); ex.getResponseBody().write(b); ex.close();
        });
        s.start();
        System.out.println("stub up");
    }
}
EOF
